/* 浮点转 1 位小数字符串, 不依赖 printf 浮点库, MCU 可直接用 */
static void fmt_1dec(char *buf, size_t size, float v)
{
    int neg = (v < 0.0f);
    if (neg) v = -v;
    int ip = (int)v;
    int fp = (int)(v * 10.0f + 0.5f) % 10;
    snprintf(buf, size, "%s%d.%d", neg ? "-" : "", ip, fp);
}

/* 纯色圆点 */
static lv_obj_t * create_dot(lv_obj_t *parent, lv_color_t color, lv_coord_t size)
{
    lv_obj_t *dot = lv_obj_create(parent);
    lv_obj_set_size(dot, size, size);
    lv_obj_set_style_radius(dot, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_color(dot, color, 0);
    lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(dot, 0, 0);
    lv_obj_set_style_pad_all(dot, 0, 0);
    lv_obj_clear_flag(dot, LV_OBJ_FLAG_SCROLLABLE);
    return dot;
}

/* 数据卡片: 标题(左上) + 圆形图标(右上) + 大数值 + 底部进度条 */
static void create_card(lv_obj_t **container, lv_obj_t *parent,
                        lv_coord_t x, lv_coord_t y,
                        lv_color_t accent, const char *title, const char *icon,
                        lv_obj_t **value_out, lv_obj_t **bar_out)
{
    *container = lv_obj_create(parent);
    lv_obj_t *card = *container;
    lv_obj_set_pos(card, x, y);
    lv_obj_set_size(card, 360, 250);
    lv_obj_set_style_bg_color(card, COL_CARD, 0);
    lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(card, 18, 0);
    lv_obj_set_style_border_color(card, COL_CARD_BRD, 0);
    lv_obj_set_style_border_width(card, 1, 0);
    lv_obj_set_style_shadow_width(card, 40, 0);
    lv_obj_set_style_shadow_color(card, lv_color_hex(0x000000), 0);
    lv_obj_set_style_shadow_opa(card, LV_OPA_30, 0);
    lv_obj_set_style_pad_all(card, 18, 0);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_CLICKABLE);

    /* 标题 */
    lv_obj_t *lab = lv_label_create(card);
    lv_label_set_text(lab, title);
    lv_obj_set_style_text_font(lab, FONT_CN20, 0);
    lv_obj_set_style_text_color(lab, COL_SUBTEXT, 0);
    lv_obj_align(lab, LV_ALIGN_TOP_LEFT, 0, 4);

    /* 圆形图标 */
    lv_obj_t *icon_bg = create_dot(card, accent, 52);
    lv_obj_set_style_bg_opa(icon_bg, LV_OPA_20, 0);
    lv_obj_align(icon_bg, LV_ALIGN_TOP_RIGHT, 0, 0);
    lv_obj_t *icon_lab = lv_label_create(icon_bg);
    lv_label_set_text(icon_lab, icon);
    lv_obj_set_style_text_font(icon_lab, FONT_MID, 0);
    lv_obj_set_style_text_color(icon_lab, accent, 0);
    lv_obj_center(icon_lab);

    /* 大数值 */
    *value_out = lv_label_create(card);
    lv_obj_set_style_text_font(*value_out, FONT_VALUE, 0);
    lv_obj_set_style_text_color(*value_out, accent, 0);
    lv_label_set_text(*value_out, "--");
    lv_obj_align(*value_out, LV_ALIGN_LEFT_MID, 0, 0);

    /* 进度条 */
    *bar_out = lv_bar_create(card);
    lv_obj_set_size(*bar_out, lv_pct(100), 10);
    lv_obj_align(*bar_out, LV_ALIGN_BOTTOM_LEFT, 0, 0);
    lv_obj_set_style_bg_color(*bar_out, COL_BG, LV_PART_MAIN);
    lv_obj_set_style_bg_opa(*bar_out, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_radius(*bar_out, 5, LV_PART_MAIN);
    lv_obj_set_style_bg_color(*bar_out, accent, LV_PART_INDICATOR);
    lv_obj_set_style_radius(*bar_out, 5, LV_PART_INDICATOR);
}

