/* ================= 刷新接口 (供 app_data.c 调用) ================= */

void ui_update_time(int32_t hour, int32_t minute, int32_t second)
{
    if (s_label_time == NULL) return;
    char buf[16];
    snprintf(buf, sizeof(buf), "%02d:%02d:%02d",
             (int)hour, (int)minute, (int)second);
    lv_label_set_text(s_label_time, buf);
}

void ui_update_date(int32_t year, int32_t month, int32_t day, int32_t weekday)
{
    if (s_label_date == NULL) return;
    static const char *wk[] = {"日", "一", "二", "三", "四", "五", "六"};
    if (weekday < 0 || weekday > 6) weekday = 0;
    char buf[48];
    snprintf(buf, sizeof(buf), "%d年%02d月%02d日 星期%s",
             (int)year, (int)month, (int)day, wk[weekday]);
    lv_label_set_text(s_label_date, buf);
}

void ui_update_temperature(float temp_c)
{
    if (ui_Labeloftemp == NULL) return;
    char v[16], buf[32];
    fmt_1dec(v, sizeof(v), temp_c);
    snprintf(buf, sizeof(buf), "%s °C", v);
    lv_label_set_text(ui_Labeloftemp, buf);

    if (s_bar_temp != NULL)
        lv_bar_set_value(s_bar_temp, (int32_t)(temp_c * 10.0f), LV_ANIM_ON);
}

void ui_update_humidity(float humi_pct)
{
    if (ui_Labelofhum == NULL) return;
    char v[16], buf[32];
    fmt_1dec(v, sizeof(v), humi_pct);
    snprintf(buf, sizeof(buf), "%s %%RH", v);
    lv_label_set_text(ui_Labelofhum, buf);

    if (s_bar_humi != NULL) {
        if (humi_pct < 0.0f)   humi_pct = 0.0f;
        if (humi_pct > 100.0f) humi_pct = 100.0f;
        lv_bar_set_value(s_bar_humi, (int32_t)humi_pct, LV_ANIM_ON);
    }
}

void ui_update_stats(float t_min, float t_max, float h_min, float h_max)
{
    if (s_label_stats == NULL) return;
    char t1[16], t2[16], h1[16], h2[16], buf[96];
    fmt_1dec(t1, sizeof(t1), t_min);
    fmt_1dec(t2, sizeof(t2), t_max);
    fmt_1dec(h1, sizeof(h1), h_min);
    fmt_1dec(h2, sizeof(h2), h_max);
    snprintf(buf, sizeof(buf), "今日 %s ~ %s °C   %s ~ %s %%RH",
             t1, t2, h1, h2);
    lv_label_set_text(s_label_stats, buf);
}

